0.text:
Async patterns for Sairin.
useDeferred
Defer signal updates to the next tick.
import { signal, useDeferred, path } from &#x27;sairin&#x27;;

const count = signal(path(&quot;counter&quot;), 0);
const deferred = useDeferred(count);

count.set(1);  // deferred still 0
count.set(2);  // deferred still 0

// After microtask:
console.log(deferred.get());  // 2

Options
useDeferred(signal, { timeoutMs: 1000 });
// Forces update after timeout if no changes

useDeferredValue
Defer a value, creating a signal.
import { useDeferredValue, signal } from &#x27;sairin&#x27;;

const deferred = useDeferredValue(42);
console.log(deferred.get());  // 42

With signal:
const source = signal(path(&quot;source&quot;), &quot;hello&quot;);
const deferred = useDeferredValue(source);

resource
Async data fetching with loading/error states.
import { resource } from &#x27;sairin&#x27;;

const userResource = resource(async (signal) =&gt; {
  const res = await fetch(&quot;/api/user&quot;, { signal });
  return res.json();
});

Returns
interface Resource&lt;T&gt; {
  loading: Signal&lt;boolean&gt;;
  error: Signal&lt;Error | null&gt;;
  data: Signal&lt;T | null&gt;;
  read: () =&gt; T | null;
  reload: () =&gt; void;
  abort: () =&gt; void;
}

Usage
const user = userResource.read();

userResource.loading.get();  // true/false
userResource.error.get();    // Error or null
userResource.data.get();     // T or null

userResource.reload();

userResource.abort();

1.text:
Context provides a way to pass values through the component tree without prop drilling.
Overview
Sairin’s context system uses a stack-based approach, allowing for nested providers with automatic cleanup.
import { createContext, useContext } from &#x27;sairin&#x27;;


createContext
Create a new context with a default value.
function createContext&lt;T&gt;(defaultValue: T, name?: string): Context&lt;T&gt;

const themeContext = createContext(&#x27;light&#x27;);
const userContext = createContext&lt;User | null&gt;(null);


Context Interface
interface Context&lt;T&gt; {
  defaultValue: T;
  Provider: (props: { value: T; children?: any }) =&gt; () =&gt; void;
  consume: () =&gt; T;
}

Provider
A component that provides a value to its children. Returns a cleanup function.
const cleanup = themeContext.Provider({ value: &#x27;dark&#x27; });
// ... components can now read &#x27;dark&#x27;
cleanup();
// ... back to default value

consume
Read the current value from the context.
const currentValue = themeContext.consume();


useContext
Hook to read a context value.
function useContext&lt;T&gt;(context: Context&lt;T&gt;): T

const theme = useContext(themeContext);


useContextProvider
Convenience function to set up a provider.
function useContextProvider&lt;T&gt;(
  context: Context&lt;T&gt;,
  value: T,
): () =&gt; void

const cleanup = useContextProvider(themeContext, &#x27;dark&#x27;);


Example
import { createContext, useContext, useContextProvider } from &#x27;sairin&#x27;;

const ThemeContext = createContext(&#x27;light&#x27;);
const UserContext = createContext&lt;{ name: string } | null&gt;(null);

function App() {
  // Provide theme
  const cleanupTheme = useContextProvider(ThemeContext, &#x27;dark&#x27;);

  // Provide user
  const cleanupUser = useContextProvider(UserContext, { name: &#x27;Alice&#x27; });

  // Clean up on unmount
  return () =&gt; {
    cleanupTheme();
    cleanupUser();
  };
}

function Header() {
  const theme = useContext(ThemeContext);
  const user = useContext(UserContext);

  return `${user?.name} using ${theme} theme`;
}


Nested Providers
Contexts can be nested, and the inner provider shadows the outer one:
const ctx = createContext(&#x27;root&#x27;);

const cleanup1 = ctx.Provider({ value: &#x27;outer&#x27; });
console.log(ctx.consume()); // &#x27;outer&#x27;

const cleanup2 = ctx.Provider({ value: &#x27;inner&#x27; });
console.log(ctx.consume()); // &#x27;inner&#x27;

cleanup2();
console.log(ctx.consume()); // &#x27;outer&#x27;

cleanup1();
console.log(ctx.consume()); // &#x27;root&#x27;

2.text:
Debug utilities for monitoring and inspecting Sairin’s reactive graph.
import { enableDebug, captureGraph } from &#x27;sairin&#x27;;


Debug Hooks
Enable debug hooks to receive notifications about reactive operations.
DebugHooks Interface
interface DebugHooks {
  onSignalCreated?: (signal: Signal&lt;any&gt;, name?: string) =&gt; void;
  onSignalRead?: (signal: Signal&lt;any&gt;) =&gt; void;
  onSignalWritten?: (signal: Signal&lt;any&gt;, oldValue: any, newValue: any) =&gt; void;
  onEffectCreated?: (effect: () =&gt; void) =&gt; void;
  onEffectRun?: (effect: () =&gt; void) =&gt; void;
  onDerivedInvalidated?: (derived: Derived&lt;any&gt;) =&gt; void;
}

enableDebug
Enable debug hooks.
function enableDebug(hooks: Partial&lt;DebugHooks&gt;): void

enableDebug({
  onSignalCreated: (signal, name) =&gt; {
    console.log(&#x27;Signal created:&#x27;, name, signal.path);
  },
  onSignalWritten: (signal, oldVal, newVal) =&gt; {
    console.log(&#x27;Signal updated:&#x27;, signal.path, oldVal, &#x27;-&gt;&#x27;, newVal);
  },
});

disableDebug
Reset all debug hooks to no-ops.
function disableDebug(): void

getDebugHooks
Get the current debug hooks configuration.
function getDebugHooks(): DebugHooks


Manual Notifications
notifySignalCreated
Manually notify that a signal was created.
function notifySignalCreated(signal: Signal&lt;any&gt;, name?: string): void

notifySignalRead
Manually notify that a signal was read.
function notifySignalWritten(
  signal: Signal&lt;any&gt;,
  oldValue: any,
  newValue: any,
): void

notifyEffectCreated
Manually notify that an effect was created.
function notifyEffectCreated(effect: () =&gt; void): void

notifyEffectRun
Manually notify that an effect ran.
function notifyEffectRun(effect: () =&gt; void): void


Graph Inspection
registerSignal
Register a signal for graph inspection.
function registerSignal(signal: Signal&lt;any&gt;): void

registerEffect
Register an effect for graph inspection.
function registerEffect(effect: () =&gt; void, id: number): void

registerDerived
Register a derived value for graph inspection.
function registerDerived(derived: Derived&lt;any&gt;): void

captureGraph
Capture a snapshot of the current reactive graph.
function captureGraph(): GraphSnapshot

interface GraphSnapshot {
  signals: GraphSnapshotSignal[];
  effects: GraphSnapshotEffect[];
  derived: GraphSnapshotDerived[];
}

clearGraph
Clear all registered signals, effects, and derived values.
function clearGraph(): void


Example
import { 
  enableDebug, 
  disableDebug,
  registerSignal, 
  captureGraph,
  clearGraph 
} from &#x27;sairin&#x27;;

// Enable debugging
enableDebug({
  onSignalCreated: (sig) =&gt; {
    console.log(&#x27;Created:&#x27;, sig.path.raw);
  },
});

// Register signals for inspection
const count = new Signal(path(&quot;counter&quot;, &quot;value&quot;), 0);
registerSignal(count);

const name = new Signal(path(&quot;user&quot;, &quot;name&quot;), &quot;Alice&quot;);
registerSignal(name);

// Capture current state
const snapshot = captureGraph();
console.log(&#x27;Signals:&#x27;, snapshot.signals.map(s =&gt; ({
  path: s.id,
  value: s.value,
  subscribers: s.subscriberCount,
})));

// Clean up when done
clearGraph();
disableDebug();

3.text:
DOM bindings connect reactive signals to DOM elements. Each binding returns a cleanup function.
Setup
Import bindings from sairin:
import { bindText, bindEvent, bindInputValue } from &#x27;sairin&#x27;;

All bindings return a cleanup function:
const cleanup = bindText(element, mySignal);
cleanup(); // Remove the binding


Text &amp; HTML
bindText
Bind element text content to a signal.
function bindText(el: Node, readable: Readable&lt;string&gt;): () =&gt; void

const name = signal(path(&quot;user&quot;, &quot;name&quot;), &quot;World&quot;);
bindText(document.querySelector(&#x27;#greeting&#x27;), name);

bindHtml
Bind element innerHTML to a signal.
function bindHtml(el: Element, readable: Readable&lt;string&gt;): () =&gt; void


Attributes &amp; Properties
bindAttribute
Bind an element attribute to a signal.
function bindAttribute(
  el: Element,
  attr: string,
  readable: Readable&lt;any&gt;
): () =&gt; void

// Sets or removes the attribute based on value
bindAttribute(img, &#x27;src&#x27;, imageUrl);        // &lt;img src=&quot;...&quot;&gt;
bindAttribute(div, &#x27;data-id&#x27;, itemId);      // &lt;div data-id=&quot;...&quot;&gt;
bindAttribute(input, &#x27;placeholder&#x27;, hint);   // &lt;input placeholder=&quot;...&quot;&gt;

bindProperty
Bind an element property to a signal.
function bindProperty&lt;T extends Element, K extends keyof T&gt;(
  el: T,
  prop: K,
  readable: Readable&lt;T[K]&gt;
): () =&gt; void

// Direct property assignment
bindProperty(canvas, &#x27;width&#x27;, canvasWidth);
bindProperty(input, &#x27;disabled&#x27;, isDisabled);


Classes &amp; Styles
bindClass
Bind an element’s className to a signal.
function bindClass(el: Element, readable: Readable&lt;string&gt;): () =&gt; void

bindClass(button, themeClass);  // button.className = themeClass.get()

bindStyle
Bind a single CSS property to a signal.
function bindStyle(
  el: HTMLElement,
  styleProp: string,
  readable: Readable&lt;string&gt;
): () =&gt; void

bindStyle(progress, &#x27;width&#x27;, progressWidth);  // progress.style.width = &quot;50%&quot;
bindStyle(box, &#x27;color&#x27;, textColor);


Visibility &amp; State
bindVisibility
Show or hide an element based on a boolean signal.
function bindVisibility(el: Element, readable: Readable&lt;boolean&gt;): () =&gt; void

bindVisibility(modal, isOpen);  // Adds/removes &quot;hidden&quot; attribute

bindDisabled
Enable or disable an element based on a boolean signal.
function bindDisabled(el: Element, readable: Readable&lt;boolean&gt;): () =&gt; void

bindDisabled(submitBtn, isSubmitting);  // Adds/removes &quot;disabled&quot; attribute

bindBooleanAttribute
Add or remove a boolean attribute based on a signal value.
function bindBooleanAttribute(
  el: Element,
  attr: string,
  readable: Readable&lt;boolean&gt;
): () =&gt; void

bindBooleanAttribute(div, &#x27;hidden&#x27;, isHidden);      // &lt;div hidden&gt;
bindBooleanAttribute(input, &#x27;required&#x27;, isRequired);    // &lt;input required&gt;

bindElementSignal
Move an element into/out of a parent based on a signal value.
function bindElementSignal&lt;T extends Element&gt;(
  el: T,
  sig: Signal&lt;T | null&gt;,
  parent: Element
): () =&gt; void


Events
bindEvent
Attach an event listener with automatic cleanup.
function bindEvent&lt;T extends Element&gt;(
  el: T,
  eventName: string,
  handler: (event: Event) =&gt; void,
  options?: AddEventListenerOptions
): () =&gt; void

bindEvent(button, &#x27;click&#x27;, () =&gt; {
  count.set(count.get() + 1);
});

bindEvent(input, &#x27;input&#x27;, (e) =&gt; {
  value.set((e.target as HTMLInputElement).value);
});


Form Inputs
bindInputValue
Two-way bind an input’s value to a signal.
function bindInputValue(
  input: HTMLInputElement | HTMLTextAreaElement,
  sig: Readable&lt;string&gt;
): () =&gt; void

const username = signal(path(&quot;form&quot;, &quot;username&quot;), &quot;&quot;);
bindInputValue(document.querySelector(&#x27;#username&#x27;), username);

bindInputChecked
Two-way bind a checkbox or radio’s checked state.
function bindInputChecked(
  input: HTMLInputElement,
  sig: Readable&lt;boolean&gt;
): () =&gt; void

const agreed = signal(path(&quot;form&quot;, &quot;agreed&quot;), false);
bindInputChecked(document.querySelector(&#x27;#agree&#x27;), agreed);

bindSelectValue
Two-way bind a select element’s value.
function bindSelectValue(
  select: HTMLSelectElement,
  sig: Readable&lt;string&gt;
): () =&gt; void

const color = signal(path(&quot;settings&quot;, &quot;color&quot;), &quot;blue&quot;);
bindSelectValue(document.querySelector(&#x27;#color-select&#x27;), color);


Readable Type
Most bindings accept a Readable&lt;T&gt;:
type Readable&lt;T&gt; = Signal&lt;T&gt; | Derived&lt;T&gt;;

This means you can pass either a signal or a derived value to any binding.

4.text:
Async flow control utilities.
flow
Execute an async operation with state signals.
import { flow } from &#x27;sairin&#x27;;

const fetchUser = flow(async (signal) =&gt; {
  const response = await fetch(&quot;/api/user&quot;, { signal });
  return response.json();
});

Returns
interface Flow&lt;T&gt; {
  running: Signal&lt;boolean&gt;;
  result: Signal&lt;T | null&gt;;
  error: Signal&lt;Error | null&gt;;
  start: () =&gt; Promise&lt;void&gt;;
  cancel: () =&gt; void;
}

Usage
await fetchUser.start();

console.log(fetchUser.running.get());  // false
console.log(fetchUser.result.get());    // { ... }
console.log(fetchUser.error.get());     // null or Error

fetchUser.cancel();

pipeline
Async operation with input.
import { pipeline } from &#x27;sairin&#x27;;

const processData = pipeline(async (input, signal) =&gt; {
  const result = await fetch(`/api/process/${input}`, { signal });
  return result.json();
});

Returns
interface Pipeline&lt;T, R&gt; {
  running: Signal&lt;boolean&gt;;
  result: Signal&lt;R | null&gt;;
  error: Signal&lt;Error | null&gt;;
  start: (input: T) =&gt; Promise&lt;void&gt;;
  cancel: () =&gt; void;
}

sequence
Run functions in sequence, collect all results.
import { sequence } from &#x27;sairin&#x27;;

const seq = sequence(
  async () =&gt; &quot;a&quot;,
  async () =&gt; &quot;b&quot;,
  async () =&gt; &quot;c&quot;
);

await seq.start();

console.log(seq.results.get());  // [&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]
console.log(seq.errors.get());    // []

parallel
Run functions in parallel.
import { parallel } from &#x27;sairin&#x27;;

const par = parallel(
  () =&gt; fetch(&quot;/api/1&quot;),
  () =&gt; fetch(&quot;/api/2&quot;),
  () =&gt; fetch(&quot;/api/3&quot;)
);

await par.start();

race
First to settle wins.
import { race } from &#x27;sairin&#x27;;

const winner = race(
  () =&gt; fetch(&quot;/api/fast&quot;),
  () =&gt; fetch(&quot;/api/slow&quot;)
);

await winner.start();

console.log(winner.winner.get());  // 0 or 1

